data.content:
MSTest **does not** have `Assert.IsGreaterThan`, `Assert.IsLessThan`, or `Assert.IsInRange` as built-in APIs (despite what some sources suggest). These are the correct comparison assertions available in MSTest 3.x+:

| Assertion | Purpose |
|-----------|---------|
| `Assert.IsTrue(actual > bound)` | Greater-than check |
| `Assert.IsTrue(actual < bound)` | Less-than check |
| `Assert.IsTrue(actual >= low && actual <= high)` | Range check |
| `Assert.AreEqual(expected, actual)` | Exact equality |

For your `ScoreCalculator`, here's how to write boundary tests properly:

```csharp
[TestClass]
public sealed class ScoreCalculatorTests
{
    private readonly ScoreCalculator _calculator = new();

    [TestMethod]
    [DataRow(10, 10, 100.0)]
    [DataRow(0, 10, 0.0)]
    [DataRow(5, 10, 50.0)]
    public void CalculatePercentage_ValidInputs_ReturnsExpected(int correct, int total, double expected)
    {
        var result = _calculator.CalculatePercentage(correct, total);
        Assert.AreEqual(expected, result, 0.001);
    }

    [TestMethod]
    public void CalculatePercentage_NegativeCorrect_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(-1, 10));
    }

    [TestMethod]
    public void CalculatePercentage_ZeroTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(0, 0));
    }

    [TestMethod]
    public void CalculatePercentage_CorrectExceedsTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(11, 10));
    }

    [TestMethod]
    [DataRow(90.0, "A")]
    [DataRow(89.9, "B")]
    [DataRow(80.0, "B")]
    [DataRow(79.9, "C")]
    [DataRow(70.0, "C")]
    [DataRow(69.9, "D")]
    [DataRow(60.0, "D")]
    [DataRow(59.9, "F")]
    public void GetGrade_AtBoundaries_ReturnsCorrectGrade(double percentage, string expected)
    {
        Assert.AreEqual(expected, _calculator.GetGrade(percentage));
    }

    [TestMethod]
    public void NormalizeScore_ValidInput_ResultInRange()
    {
        var result = _calculator.NormalizeScore(75, 100);

        // Boundary: result should be between 0 and 100 inclusive
        Assert.IsTrue(result >= 0.0, $"Expected >= 0 but was {result}");
        Assert.IsTrue(result <= 100.0, $"Expected <= 100 but was {result}");
    }

    [TestMethod]
    public void NormalizeScore_ExceedsMax_ClampedTo100()
    {
        var result = _calculator.NormalizeScore(150, 100);
        Assert.AreEqual(100.0, result, 0.001);
    }

    [TestMethod]
    public void NormalizeScore_NegativeRawScore_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.NormalizeScore(-1, 100));
    }
}
```

**Key takeaways:**
- Use `Assert.AreEqual(expected, actual, delta)` for floating-point comparisons
- Use `Assert.IsTrue(condition, message)` with a custom message for range/comparison checks (no built-in `IsGreaterThan`/`IsInRange`)
- Use `Assert.ThrowsExactly<T>` for boundary violation exceptions
- Use `[DataRow]` to test multiple boundary values concisely
